import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }],
  };
  const typography = visualSpec.typography ?? {
    wordmark: { fontSize: 34, letterSpacing: 0.02 },
    'column-header': { fontSize: 9, letterSpacing: 0.12 },
    link: { fontSize: 13, letterSpacing: 0 },
    legal: { fontSize: 9, letterSpacing: 0.04 },
  };

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const wordmarkText = items.find((i) => i.role === 'wordmark')?.text ?? 'NOVA ATELIER';
  const headerTexts = items.filter((i) => i.role === 'column-header').map((i) => i.text);
  const linkTexts = items.filter((i) => i.role === 'link').map((i) => i.text);
  const legalText = items.find((i) => i.role === 'legal')?.text ??
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.';

  const headers = headerTexts.length === 3 ? headerTexts : ['ATELIER', 'COMPANY', 'LEGAL'];
  const columnLinks = [
    linkTexts.slice(0, 3).length === 3 ? linkTexts.slice(0, 3) : ['Features', 'Collection', 'Pricing'],
    linkTexts.slice(3, 6).length === 3 ? linkTexts.slice(3, 6) : ['Journal', 'Visit the Atelier', 'Contact'],
    linkTexts.slice(6, 9).length === 3 ? linkTexts.slice(6, 9) : ['Privacy', 'Terms', 'Warranty'],
  ];

  const group = new Group();
  group.name = 'footer-colophon';

  const disposables = [];
  const primitiveHandles = [];
  const textObjects = [];

  // ---- Backdrop band: 6.8 x 2.0, vertical gradient ----
  const bandW = 6.8;
  const bandH = 2.0;
  const gradientStops = colors.gradientStops ?? [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }];
  const topHex = gradientStops[0]?.hex ?? '#121218';
  const bottomHex = gradientStops[gradientStops.length - 1]?.hex ?? '#0b0b10';

  const bandGeo = new PlaneGeometry(bandW, bandH, 1, 1);
  const bandMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2 });
  bandMat.transparent = true;
  bandMat.opacity = 0;
  bandMat.colorNode = mix(color(bottomHex), color(topHex), uv().y);
  const bandMesh = new Mesh(bandGeo, bandMat);
  bandMesh.position.set(0, 0, 0);
  group.add(bandMesh);
  disposables.push(bandGeo, bandMat);

  // ---- Hairline rules ----
  function makeHairline(y, width) {
    const geo = new PlaneGeometry(width, 0.006, 1, 1);
    const mat = new MeshStandardNodeMaterial({ roughness: 0.4, metalness: 0.55 });
    mat.transparent = true;
    mat.opacity = 0;
    mat.colorNode = color('#23232b');
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, y, 0.002);
    group.add(mesh);
    disposables.push(geo, mat);
    return mesh;
  }

  const hairlineTop = makeHairline(bandH / 2 - 0.003, bandW);
  const hairlineLegal = makeHairline(-0.375, bandW);

  // ---- Accent bar under wordmark ----
  const accentGeo = new PlaneGeometry(0.3, 0.02, 1, 1);
  const accentMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.3 });
  accentMat.transparent = true;
  accentMat.opacity = 0;
  accentMat.colorNode = color(colors.accent);
  accentMat.emissiveNode = color(colors.accent).mul(1.4);
  const accentMesh = new Mesh(accentGeo, accentMat);
  const wordmarkBlockLeft = -bandW / 2;
  accentMesh.position.set(wordmarkBlockLeft + 0.15, 0.28, 0.002);
  group.add(accentMesh);
  disposables.push(accentGeo, accentMat);

  // ---- Local rim light (opposite the upper-left key) ----
  const rimLight = new DirectionalLight(new Color(colors.paper), 0.7);
  rimLight.position.set(3, -1.5, 3);
  group.add(rimLight);

  // ---- Text layout ----
  const TEXT_SCALE = 0.01;
  function addText(str, opts, x, y, z = 0.003) {
    const textObj = ctx.fontAtlas.createText(str, opts);
    textObj.scale.setScalar(TEXT_SCALE);
    textObj.position.set(x, y, z);
    group.add(textObj);
    textObjects.push(textObj);
    return textObj;
  }

  // Wordmark
  const wordmarkTypo = typography.wordmark ?? { fontSize: 34, letterSpacing: 0.02 };
  addText(wordmarkText, {
    fontSize: wordmarkTypo.fontSize ?? 34,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: (wordmarkTypo.fontSize ?? 34) * (wordmarkTypo.letterSpacing ?? 0.02),
  }, wordmarkBlockLeft, 0.55);

  // Columns
  const colHeaderTypo = typography['column-header'] ?? { fontSize: 9, letterSpacing: 0.12 };
  const linkTypo = typography.link ?? { fontSize: 13, letterSpacing: 0 };
  const gutter = 0.375;
  const colWidth = 1.2;
  const wordmarkBlockWidth = 2.0;
  const col1X = wordmarkBlockLeft + wordmarkBlockWidth + gutter;
  const colXs = [col1X, col1X + colWidth + gutter, col1X + 2 * (colWidth + gutter)];

  const linkMeshRegistry = [];

  for (let c = 0; c < 3; c += 1) {
    const x = colXs[c];
    addText(headers[c], {
      fontSize: colHeaderTypo.fontSize ?? 9,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: (colHeaderTypo.fontSize ?? 9) * (colHeaderTypo.letterSpacing ?? 0.12),
    }, x, 0.62);

    const linkYs = [0.32, 0.08, -0.16];
    for (let r = 0; r < 3; r += 1) {
      const linkObj = addText(columnLinks[c][r], {
        fontSize: linkTypo.fontSize ?? 13,
        color: colors.paper,
        align: 'left',
        letterSpacingPx: (linkTypo.fontSize ?? 13) * (linkTypo.letterSpacing ?? 0),
      }, x, linkYs[r]);
      linkMeshRegistry.push(linkObj);
    }
  }

  // Legal line
  const legalTypo = typography.legal ?? { fontSize: 9, letterSpacing: 0.04 };
  addText(legalText, {
    fontSize: legalTypo.fontSize ?? 9,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: (legalTypo.fontSize ?? 9) * (legalTypo.letterSpacing ?? 0.04),
  }, 0, -0.625);

  // ---- Cinematic primitives (data-driven, none configured by default) ----
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Mount animation: single fade-up of the whole band ----
  function collectMaterials(obj, out) {
    obj.traverse?.((child) => {
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        for (const m of mats) {
          if (m) {
            m.transparent = true;
            out.push(m);
          }
        }
      }
    });
  }
  const fadeMaterials = [bandMat, accentMat, hairlineTop.material, hairlineLegal.material];
  for (const t of textObjects) collectMaterials(t, fadeMaterials);
  for (const m of fadeMaterials) {
    if (typeof m.opacity === 'number') m.opacity = 0;
  }

  group.position.y += 0.2;
  const opacityProxy = { v: 0 };
  const tl = gsap.timeline();
  tl.to(group.position, { y: group.position.y - 0.2, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(opacityProxy, {
    v: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      for (const m of fadeMaterials) {
        if (typeof m.opacity === 'number') {
          m.opacity = opacityProxy.v;
          m.needsUpdate = true;
        }
      }
    },
  }, 0);

  // ---- Minimal hover support for links (color: paper -> accent) ----
  function tweenLinkColor(linkObj, hex) {
    linkObj.traverse?.((child) => {
      if (child.material && child.material.color) {
        gsap.to(child.material.color, {
          r: new Color(hex).r,
          g: new Color(hex).g,
          b: new Color(hex).b,
          duration: 0.14,
          ease: 'power2.out',
        });
      }
    });
  }

  group.userData.handlers = {
    onPointerOver: (evt) => {
      const target = evt?.object ?? evt;
      if (linkMeshRegistry.includes(target)) {
        tweenLinkColor(target, colors.accent);
        gsap.to(target.position, { z: 0.02, duration: 0.14, ease: 'power2.out' });
      }
    },
    onPointerOut: (evt) => {
      const target = evt?.object ?? evt;
      if (linkMeshRegistry.includes(target)) {
        tweenLinkColor(target, colors.paper);
        gsap.to(target.position, { z: 0.003, duration: 0.14, ease: 'power2.out' });
      }
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    for (const handle of primitiveHandles) {
      try {
        handle.cleanup?.();
      } catch (e) {
        // no-op
      }
    }
    for (const geoOrMat of disposables) {
      geoOrMat?.dispose?.();
    }
    for (const t of textObjects) {
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        for (const m of mats) m?.dispose?.();
      });
      group.remove(t);
    }
    group.remove(rimLight);
    group.remove(bandMesh, hairlineTop, hairlineLegal, accentMesh);
  };

  return group;
}
